param([switch]$ExecutionAuthorized)
# Exactly one immutable pure-reader call; no solver, build, relink or automatic retry.
$ErrorActionPreference='Stop';$tests=Split-Path -Parent $PSScriptRoot;$case=Split-Path -Parent $tests;$logs=Join-Path $tests 'logs';$tag='upl_gpu_column_off_r1'
$folder=Join-Path $tests ('outputs\'+$tag);$review=Join-Path $tests ('outputs\'+$tag+'_native');$record=Join-Path $logs ($tag+'.exact.json');$callPath=Join-Path $logs ($tag+'_reader.call.json');$log=Join-Path $logs ($tag+'_reader.log')
function E([string]$p){$f=Get-Item -LiteralPath $p -Force;[ordered]@{path=$f.FullName;bytes=[long]$f.Length;sha256=(Get-FileHash -LiteralPath $p -Algorithm SHA256).Hash.ToLowerInvariant()}}
function J([string]$p){[IO.File]::ReadAllText($p)|ConvertFrom-Json}
function V($rows){foreach($r in $rows){if(!$r.path){throw 'Missing bound Entry'};$a=E $r.path;if($a.bytes -ne $r.bytes -or $a.sha256 -ine $r.sha256){throw "Changed artifact: $($r.path)"}}}
function Need([bool]$yes,[string]$why){if(!$yes){throw $why}}
function Fresh($paths){foreach($p in $paths){Need (!(Test-Path -LiteralPath $p)) ("Retained path protected: "+$p)}}
function Save([string]$p,$v){Fresh @($p);[IO.File]::WriteAllText($p,($v|ConvertTo-Json -Depth 18)+[Environment]::NewLine,(New-Object Text.UTF8Encoding($false)))}
function N($v){Need ($null -ne $v -and [string]$v -ne '') 'Missing number';$n=if($v -is [ValueType]){[double]$v}else{[double]::Parse([string]$v,[Globalization.CultureInfo]::InvariantCulture)};Need (![double]::IsNaN($n) -and ![double]::IsInfinity($n)) 'Nonfinite number';return $n}
function Owned($entry){V @($entry);$c=J $entry.path;Need ($c.owned_call_exited -and $c.typed_LASTEXITCODE_captured_immediately -and $c.exit_code -is [int] -and $c.exit_code -eq 0) 'Owned immediate typed native exit0 required';V @($c.program,$c.log)}
Need $ExecutionAuthorized 'Root full-read plus explicit one-reader authorization required';Fresh @($review,$record,$callPath,$log)
$runPath=Join-Path $logs ($tag+'.run.json');$r=J $runPath;Need ($r.passed -and $r.source_input_runtime_canonical_unchanged -and $r.fresh_solver_calls -eq 1 -and !$r.old_solver_rerun -and $r.physical_acceptance -eq $false) 'Passed new owned OFF run required'
Owned $r.call;$solver=J $r.call.path;Need ($solver.actual_solver_call) 'Actual new solver ownership missing';$m=J $r.input.path;$d=J $r.completion.path
Need ($d.passed_owned_exit_and_bindings_only -and $d.typed_LASTEXITCODE_captured_immediately -and $d.owned_exited -and $d.exit_code -is [int] -and $d.exit_code -eq 0 -and $d.source_input_control_runtime_canonical_unchanged -and @($d.survivors).Count -eq 0) 'New run completion/bindings-only gate rejected'
$b=J $r.source_build.path;$s=J $r.source_freeze.path
Need ($b.passed -and $b.configuration -ceq 'Release' -and $b.objects_exclude_main -and $b.source_and_protected_artifacts_unchanged -and @($b.objects).Count -eq 110 -and @($b.runtime).Count -eq 4 -and @($s.source).Count -eq 265 -and @($s.current_source_snapshot).Count -eq 265 -and @($s.canonical_programs_before).Count -eq 7 -and $r.program.sha256 -ieq $b.isolated_GPU_program.sha256 -and $solver.program.sha256 -ieq $r.program.sha256 -and $r.source_freeze.sha256 -ieq $b.source_freeze.sha256) 'Current OFF source265/objects110/runtime4/canonical7/program closure required'
$oldPath=Join-Path $logs 'upl_gpu_public_explicit_off_r1.check.json';$old=J $oldPath;$oldInput=J $old.input.path;$oldRun=J $old.source_run.path;$oldDone=J $old.solver_completion.path
Need ($old.passed -and $old.actual_main_owned_exit0_proven -and $old.all_native_typed15_and_actual_clock_step_signed_dterror_exact -and $old.dynamic_arrays_and_public_metadata_absent -and $old.original_HG_guard_preserved -and $old.native_frame_pairs -eq 151 -and $old.native_count -eq 1040 -and $old.original_arrays -eq 15 -and $m.retained_control.sha256 -ieq (E $oldPath).sha256 -and $r.retained_control.sha256 -ieq (E $oldPath).sha256) 'Sealed explicit OFF151 control required; no omission/null-exit substitute'
Owned $old.solver_call;Owned $old.call;Need ($oldDone.owned_exited -and $oldDone.exit_code -is [int] -and $oldDone.exit_code -eq 0 -and $oldInput.only_three_zero_keys_added -and $oldInput.reverse_DOM_exact) 'Old explicit owned exit/input contract rejected'
$oldData=Join-Path $oldInput.output 'data';$newData=Join-Path $folder 'data';Need ($m.retained_control_data -ieq $oldData -and $m.expected_frames -eq 151 -and $m.expected_native -eq 1040 -and $m.expected_steps -eq 15000 -and (N $m.dt_s) -eq 1e-5 -and ($solver.arguments -join [char]0) -ceq ($m.arguments -join [char]0)) 'Bound actual OFF data/clock/argv differs'
$hp=Join-Path $logs 'upl_gpu_public_off_reader_Release_r2.helper.json';$h=J $hp
Need ($h.fixture -ceq 'OffReader' -and $h.configuration -ceq 'Release' -and $h.status -ceq 'actual_authoritative_GPU_objects_helper_linked_not_run' -and $h.offline_reader_only -and $h.exact_link_closure_verified -and $h.link_object_count -eq 111 -and $h.program.sha256 -ceq '0e3eaa27ea3e422b46a119e40670b19b44dd3fe9dd8fbedd89f52718a0ed338c') 'Immutable accepted pure OFF reader required'
# These accepted historical compiler calls predate the explicit typed flag; do not invent it.
foreach($e in @($h.compile_call,$h.link_call)){V @($e);$c=J $e.path;Need ($c.owned_call_exited -and $c.exit_code -is [int] -and $c.exit_code -eq 0) 'Accepted immutable reader compiler/linker exit0 required';V @($c.program,$c.log)}
$inputs=@((E $PSCommandPath),(E (Join-Path $tests 'notes\upl_gpu_column_off_review_r1.json')),(E $runPath),$r.input,$r.completion,$r.call,$r.source_build,$r.source_freeze,$r.program,(E $oldPath),$old.input,$old.source_run,$old.solver_completion,$old.solver_call,$old.call,$old.completion,(E $hp),$h.program,$h.compile_call,$h.link_call)
function Verify{
  V $inputs;V $r.bindings;V $r.files;V $d.files;V @($solver.program,$solver.log);V $s.source;V $b.objects;V $b.tools;V $b.libraries;V @($b.project_call,$b.project_main_object,$b.isolated_GPU_program);V $s.canonical_programs_before;V $s.runtime_before;V @($s.documentation_snapshot.original,$s.documentation_snapshot.snapshot)
  foreach($p in $s.current_source_snapshot){V @($p.original,$p.snapshot)};foreach($p in $b.runtime){V @($p.original,$p.copy)}
  V $old.files;V $oldRun.files;V $oldDone.files;V @($oldInput.original_runtime_XML,$oldInput.new_runtime_XML);foreach($p in $oldInput.copied_inputs){V @($p.original,$p.copy)}
  # Reader's historic source/build identities stay in its sealed manifest, not current-source checks.
  V $h.author_files;foreach($p in $h.runtime){V @($p.copy)}
}
Verify
$argv=@('--compare',$oldData,$newData,$review);[IO.File]::WriteAllBytes($log,[byte[]]@());$start=[DateTime]::UtcNow.ToString('o');$code=$null;$launchFailure=$null;$saved=$ErrorActionPreference
Push-Location $case
try{$ErrorActionPreference='Continue';$global:LASTEXITCODE=$null;& $h.program.path @argv 2>&1|Tee-Object -FilePath $log -Append|Out-Host;$code=$LASTEXITCODE}catch{$launchFailure=$_.Exception.Message}finally{Pop-Location;$ErrorActionPreference=$saved}
Save $callPath ([ordered]@{program=$h.program;arguments=$argv;working_directory=$case;started_utc=$start;ended_utc=[DateTime]::UtcNow.ToString('o');direct_native_invocation=$true;typed_LASTEXITCODE_captured_immediately=($code -is [int]);owned_call_exited=($code -is [int]);exit_code=$code;invocation_failure=$launchFailure;log=(E $log);offline_reader_only=$true;actual_solver_call=$false;physical_acceptance=$false})
$failure=$launchFailure;$completion=$null;$files=@();$unchanged=$false;$hgValues=$null
try{
  Need ($code -is [int] -and $code -eq 0 -and !$launchFailure) 'Pure native comparison failed; never rerun solver'
  $completion=E (Join-Path $review 'complete.json');$n=J $completion.path;$rows=@(Import-Csv -LiteralPath (Join-Path $review 'comparison.csv'))
  Need ($n.passed -and $n.frames -eq 151 -and $n.native_count -eq 1040 -and $n.fixed_count -eq 40 -and $n.soil_count -eq 1000 -and $n.original_arrays -eq 15 -and $n.compared_bytes -eq 25126400 -and $n.different_bytes -eq 0 -and $n.all_native_original15_typed_bits_exact -and $n.actual_time_step_signed_dterror_exact -and $n.typed_signed_dterror_present_finite_safe -and $n.dynamic_arrays_and_metadata_absent_both -and $n.native_set_elastic_finite_no_exclusions -and $n.sequential_accumulated_binary64_clock_checked -and $n.actual_steps -eq 15000 -and (N $n.max_signed_dterror_s) -le 1e-14 -and !$n.solver_or_restart_called -and !$n.physical_acceptance -and $rows.Count -eq 151) 'Original151 native15/clock/schema gate rejected'
  for($p=0;$p -lt 151;$p++){Need ((N $rows[$p].part) -eq $p -and (N $rows[$p].arrays) -eq 15 -and (N $rows[$p].native_count) -eq 1040 -and (N $rows[$p].compared_bytes) -eq 166400 -and (N $rows[$p].different_bytes) -eq 0 -and (N $rows[$p].dterror_s) -le 1e-14) 'Complete151 per-frame CSV gate rejected';$null=N $rows[$p].time_s;$null=N $rows[$p].saved_step}
  $text=[IO.File]::ReadAllText((Join-Path $folder 'Run.out'));$steps=[regex]::Match($text,'Steps of simulation\.*:\s*(\d+)');$hg=[regex]::Match($text,'SoilHourglass: forcecalls=(\d+) predictorupdates=(\d+) correctorupdates=(\d+) ratecalls=(\d+)');$cache=[regex]::Match($text,'SoilHourglass: ratecalculations=(\d+) endpoint_rate_reuses=(\d+)');$shape=[regex]::Match($text,'max\(dt/tau\)=([^ ]+) spinbound=([^\r\n]+)')
  Need ($text.Contains('Finished execution (code=0)') -and $steps.Success -and [int]$steps.Groups[1].Value -eq 15000 -and $hg.Success -and $cache.Success -and $shape.Success) 'Actual new OFF completion/HG telemetry missing'
  Need ([int]$hg.Groups[1].Value -eq 30000 -and [int]$hg.Groups[2].Value -eq 15000 -and [int]$hg.Groups[3].Value -eq 15000 -and [int]$hg.Groups[4].Value -eq 30000 -and [int]$cache.Groups[1].Value -eq 15001 -and [int]$cache.Groups[2].Value -eq 14999 -and (N $shape.Groups[1].Value) -ge 0 -and (N $shape.Groups[1].Value) -le .2 -and (N $shape.Groups[2].Value) -ge 0 -and (N $shape.Groups[2].Value) -lt .01) 'Original HG count/cache/dt/spin guard rejected'
  $hgValues=[ordered]@{forcecalls=30000;predictorupdates=15000;correctorupdates=15000;ratecalls=30000;ratecalculations=15001;endpoint_rate_reuses=14999;max_dt_over_tau=(N $shape.Groups[1].Value);spinbound=(N $shape.Groups[2].Value)}
}catch{$failure=$_.Exception.Message}
try{Verify;$unchanged=$true}catch{if(!$failure){$failure=$_.Exception.Message}}
if(Test-Path -LiteralPath $review){$files=@(Get-ChildItem -LiteralPath $review -File|Sort-Object FullName|ForEach-Object{E $_.FullName})}
$passed=(!$failure -and $unchanged -and $null -ne $completion -and $code -is [int] -and $code -eq 0)
Save $record ([ordered]@{stage='upl_gpu_column_off_review_r1';passed=[bool]$passed;all_original15_typed_exact=[bool]$passed;actual_clock_step_dterror_exact=[bool]$passed;dynamic_arrays_and_public_metadata_absent=[bool]$passed;original_HG_guard_preserved=[bool]$passed;source_build=$r.source_build;source_freeze=$r.source_freeze;source_run=(E $runPath);retained_control=(E $oldPath);helper=(E $hp);call=(E $callPath);completion=$completion;inputs=$inputs;files=$files;source_input_raw_runtime_canonical_unchanged=$unchanged;HG_observation=$hgValues;native_frame_pairs=151;native_count=1040;original_arrays=15;compared_bytes=25126400;different_bytes=$(if($passed){0}else{$null});old_historical_source_originals_revalidated_as_current=$false;solver_or_relink_called=$false;physical_acceptance=$false;failure=$failure})
if(!$passed){throw "OFF QC rejected; preserve $record and all data, no automatic retry"}
Write-Output "One pure OFF exact comparison sealed: $record"

